-- 0280_bastion_rls.sql
-- Why: Row-level-security foundation for every bastion_* table (spec 4.3). Policies are
--   GENERATED by a DO $$ loop over information_schema for the bastion_ prefix, the
--   0251_bursar_rls.sql pattern (PG16 has no CREATE POLICY IF NOT EXISTS, so each is DROP
--   POLICY IF EXISTS then CREATE POLICY). Every Bastion table is org-scoped by
--   organization_id, so every table takes the blanket org-isolation policy; there are no
--   global rows. Pre-org lookups go through the definer resolvers in 0279, and probes through
--   the hardened definer functions with their org guard. apps/bastion-api/test/db/
--   rls-coverage.test.ts asserts every bastion_% table is covered. The spec numbers this file
--   0269; the tip had moved on.
-- Client impact: additive only. Policies are created but the connecting role is currently a
--   superuser and bypasses RLS unconditionally, so behavior is unchanged until the platform
--   arms a NOSUPERUSER / NOBYPASSRLS application role. The explicit organization_id predicate
--   in every Bastion query remains the only tenant boundary until then.

DO $$
DECLARE
    tbl text;
    pol text;
BEGIN
    FOR tbl IN
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name LIKE 'bastion\_%' ESCAPE '\'
          AND table_type = 'BASE TABLE'
        ORDER BY table_name
    LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', tbl);

        pol := tbl || '_org_isolation';
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', pol, tbl);
        EXECUTE format(
            'CREATE POLICY %I ON %I FOR ALL '
            || 'USING (organization_id = current_setting(''app.current_org_id'', true)::uuid)',
            pol, tbl);
    END LOOP;
END $$;
